mapper.select:
SELECT ip_id, tenant_id, spu_id, type, name, registration_no, jurisdiction, status, filed_at, expires_at, created_at, updated_at
FROM pdm_intellectual_property WHERE tenant_id = #{tenantId} AND spu_id = #{spuId}
ORDER BY created_at DESC

mapper.update:
UPDATE pdm_quality_standard SET name = #{name}, description = #{description}, inspection_items = #{inspectionItems},
       acceptance_criteria = #{acceptanceCriteria}, enabled = #{enabled}, updated_at = #{updatedAt}
WHERE standard_id = #{standardId} AND tenant_id = #{tenantId}

mapper.select:
SELECT standard_id, tenant_id, category_id, name, description, inspection_items, acceptance_criteria, enabled, created_at, updated_at
FROM pdm_quality_standard WHERE tenant_id = #{tenantId} AND category_id = #{categoryId}
ORDER BY created_at DESC

